# Better calculation: find each Lemma/Theorem and count lines in its proof body
awk '
  /^Lemma|^Theorem/ {
    if (lemma_start > 0) {
      size = NR - lemma_start
      if (size > 50) {
        print size " lines: " lemma_start " " lemma_name
      }
    }
    lemma_start = NR
    lemma_name = $0
    next
  }
  /^Qed\./ {
    if (lemma_start > 0) {
      size = NR - lemma_start
      if (size > 50) {
        print size " lines: " lemma_start " " lemma_name
      }
      lemma_start = 0
    }
  }
END {
  if (lemma_start > 0) {
    size = NR - lemma_start
    if (size > 50) {
      print size " lines: " lemma_start " " lemma_name
    }
  }
' /scratch/lelarge/mathcomp-eulerian/psi_descent.v | sort -rn | head -15

